<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,apiBlob,can,cents,money,PageHeader,Feedback,EmptyState,StatusBadge,useCommand,session,type Product,type Sku,type DataRow} from '@tradeflow/ui'
import {useRows,text,row} from '../data'
import Pagination from '../components/Pagination.vue'
const tab=ref('products')
const keyword=ref(''),appliedKeyword=ref('')
const products=useRows(()=>'/api/v1/merchant/products?keyword='+encodeURIComponent(appliedKeyword.value))
async function searchProducts(){appliedKeyword.value=keyword.value.trim();products.reset();await products.reload()}
const ledger=useRows(()=>'/api/v1/merchant/inventory/ledger')
const conditions=useRows(()=>'/api/v1/merchant/inventory/conditions')
const conditionForm=ref({skuId:'',fromCondition:'QUARANTINE',toCondition:'SALEABLE',quantity:'',reason:''})
const conditionLabels:Record<string,string>={SALEABLE:'可再售',QUARANTINE:'待检隔离',DAMAGED:'残次保留',SCRAPPED:'报损'}
async function changeCondition(){const g=generation;localError.value='';const f={...conditionForm.value};if(!/^[1-9][0-9]{0,18}$/.test(f.skuId)||!/^\d+$/.test(f.quantity)||!Number.isSafeInteger(Number(f.quantity))||Number(f.quantity)<1||Number(f.quantity)>1000000000||!f.reason.trim()||f.fromCondition===f.toCondition){localError.value='请填写有效SKU、正整数数量、不同目标状态及处置依据';return}const body={...f,quantity:Number(f.quantity),reason:f.reason.trim()};const result=await command.run('condition:'+f.skuId,body,key=>api('/api/v1/merchant/inventory/condition-adjustments',{method:'POST',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;notice.value='实物处置已返回，请核对不可售余额和可售流水。';await conditions.reload();await ledger.reload();await products.reload()}
/** 原表单丢失时仍可查询已受理处置；null保留原键，绝不把未查到当成失败换键。 */
async function recoverCondition(){localError.value='';const g=generation,skuId=conditionForm.value.skuId;if(!/^[1-9][0-9]{0,18}$/.test(skuId)){localError.value='请输入原处置的SKU编号';return}const result=await command.recover<{operationNo:string;skuId:string}>('condition:'+skuId,key=>api('/api/v1/merchant/inventory/condition-adjustments/requests/by-key?skuId='+encodeURIComponent(skuId),{key}));if(g!==generation)return;if(!result){if(!command.error.value)notice.value='当前账号没有此SKU的待恢复处置记录。';return}notice.value='已确认原处置 '+result.operationNo+'，请核对余额与流水。';await command.reset();if(g===generation){await conditions.reload();await ledger.reload();await products.reload()}}
const list=computed(()=>products.items.value as unknown as Product[])
const active=computed(()=>tab.value==='products'?products:tab.value==='conditions'?conditions:ledger)
const modal=ref(''),form=ref({name:'',description:'',status:'DRAFT',skuCode:'',specification:'',price:'',skuId:'',quantity:'',reason:''})
const selected=ref<Product|null>(null),sku=ref<Sku|null>(null),localError=ref(''),notice=ref('')
const command=useCommand('admin-products')
let generation=0
onBeforeUnmount(()=>{generation++;clearImages()})
function open(kind:string,p:Product|null=null,s:Sku|null=null){generation++;selected.value=p;sku.value=s;localError.value='';notice.value='';form.value={name:p?.name||'',description:p?.description||'',status:s?.status||p?.status||'DRAFT',skuCode:'',specification:'',price:s?(s.priceCents/100).toFixed(2):'',skuId:s?.skuId||'',quantity:'',reason:''};modal.value=kind}
function close(){generation++;modal.value=''}
/** 商品与SKU采用原版本乐观编辑；冲突后用户刷新核对，不静默覆盖他人的业务修改。库存受理不等于库存已落账。 */
async function submit(){localError.value='';const g=generation;const f={...form.value};let body:DataRow={},path='',method='POST'
 try{
  if(modal.value==='create'){if(!f.name.trim()||!f.skuCode.trim())throw Error('请填写商品名称与SKU编码');body={name:f.name.trim(),description:f.description,status:f.status,skus:[{skuCode:f.skuCode,specification:f.specification,priceCents:cents(f.price)}]};path='/api/v1/merchant/products'}
  if(modal.value==='addSku'&&selected.value){if(!/^[A-Za-z0-9_-]{1,64}$/.test(f.skuCode))throw Error('SKU编码仅支持1至64位字母、数字、下划线或短横线');body={skuCode:f.skuCode,specification:f.specification,priceCents:cents(f.price)};path='/api/v1/merchant/products/'+selected.value.productId+'/skus'}
  if(modal.value==='product'&&selected.value){body={version:selected.value.version,name:f.name.trim(),description:f.description,status:f.status};path='/api/v1/merchant/products/'+selected.value.productId;method='PATCH'}
  if(modal.value==='sku'&&sku.value){body={version:sku.value.version,priceCents:cents(f.price),status:f.status};path='/api/v1/merchant/skus/'+sku.value.skuId;method='PATCH'}
  if(modal.value==='inventory'){if(!/^[1-9][0-9]{0,18}$/.test(f.skuId)||! /^-?\d+$/.test(f.quantity)||!Number.isSafeInteger(Number(f.quantity))||Number(f.quantity)===0||Math.abs(Number(f.quantity))>1000000)throw Error('请填写合法SKU编号及非零整数调整量（绝对值不超过100万）');if(!f.reason.trim())throw Error('库存调整必须填写业务原因');body={warehouseId:'warehouse_main',reason:f.reason.trim(),items:[{skuId:f.skuId,quantityDelta:Number(f.quantity)}]};path='/api/v1/merchant/inventory/adjustments'}
  const kind=modal.value;const result=await command.run(`${method}:${path}`,body,key=>api<unknown>(path,{method,body,key}));if(g!==generation||result===undefined)return
  await command.reset();if(g!==generation)return;notice.value=kind==='inventory'?`调整已受理，单据 ${text(row(result).businessNo)}，当前状态 ${text(row(result).status)}。请刷新库存流水核对落账结果。`:'变更已返回，请刷新列表核对最新版本。';modal.value='';await products.reload();if(kind==='inventory')await ledger.reload()
 }catch(e){if(g===generation)localError.value=e instanceof Error?e.message:'输入参数不合法'}
}
interface ImageView {imageNo:string;productId:string;url:string;contentType:string;sizeBytes:number}
interface ImagePreview extends ImageView {preview:string;failed:boolean}
interface UploadItem {file:File;sha256:string;state:'ready'|'saved'|'unknown'}
const imageProduct=ref<Product|null>(null),imageRows=ref<ImagePreview[]>([]),imageLoading=ref(false),imageError=ref(''),imageNotice=ref(''),uploadItems=ref<UploadItem[]>([]),uploadBusy=ref(false)
const imageCommand=useCommand('admin-product-images')
let imageGeneration=0,imageController:AbortController|null=null
/** 草稿使用鉴权二进制入口；换店、关闭及离开时中止读取并释放全部ObjectURL。 */
function clearImages(){imageGeneration++;imageController?.abort();imageController=null;imageRows.value.forEach(item=>{if(item.preview)URL.revokeObjectURL(item.preview)});imageRows.value=[];imageLoading.value=false}
function closeImages(){clearImages();imageProduct.value=null;uploadItems.value=[];imageError.value='';imageNotice.value=''}
async function openImages(product:Product){closeImages();imageProduct.value=product;await loadImages()}
async function loadImages(){
 const id=imageProduct.value?.productId;if(!id)return;clearImages();const mine=imageGeneration;imageController=new AbortController();const signal=imageController.signal;imageLoading.value=true;imageError.value=''
 try{const result=await api<ImageView[]>('/api/v1/merchant/products/'+id+'/images',{signal});if(mine!==imageGeneration)return
  imageRows.value=result.map(item=>({...item,preview:'',failed:false}))
  await Promise.all(result.map(async item=>{try{const blob=await apiBlob('/api/v1/merchant/product-images/'+item.imageNo,signal);if(mine!==imageGeneration)return;const target=imageRows.value.find(row=>row.imageNo===item.imageNo);if(target)target.preview=URL.createObjectURL(blob)}catch{if(mine===imageGeneration){const target=imageRows.value.find(row=>row.imageNo===item.imageNo);if(target)target.failed=true}}}))
 }catch(reason){if(mine===imageGeneration)imageError.value=reason instanceof Error?reason.message:'图片暂时无法读取'}finally{if(mine===imageGeneration)imageLoading.value=false}
}
/** 不持久化文件正文；每个文件以内容摘要和商品建立稳定命令，刷新后重新选择同一文件仍使用原键。 */
async function selectFiles(event:Event){
 const input=event.target as HTMLInputElement,files=Array.from(input.files||[]),mine=imageGeneration;input.value='';imageError.value=''
 if(files.length>10){imageError.value='每次最多选择十张图片';return}
 const prepared:UploadItem[]=[]
 try{for(const file of files){if(!file.size||file.size>5242880||!['image/png','image/jpeg'].includes(file.type))throw Error('请选择5MiB以内的PNG或JPEG图片');const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());if(mine!==imageGeneration)return;const sha256=Array.from(new Uint8Array(digest),value=>value.toString(16).padStart(2,'0')).join('');if(!prepared.some(item=>item.sha256===sha256))prepared.push({file,sha256,state:'ready'})}if(mine===imageGeneration)uploadItems.value=prepared}catch(reason){if(mine===imageGeneration)imageError.value=reason instanceof Error?reason.message:'无法读取所选图片'}
}
/** 串行上传，任一未知立即暂停后续文件；重试保持原内容/原键，不把超时当作失败换号。 */
async function uploadImages(){
 const product=imageProduct.value;if(!product||uploadBusy.value)return;const mine=imageGeneration;uploadBusy.value=true;imageError.value='';imageNotice.value=''
 try{for(const item of uploadItems.value){if(item.state==='saved')continue;const body=new FormData();body.append('file',item.file)
  const result=await imageCommand.run('upload:'+product.productId+':'+item.sha256,{productId:product.productId,sha256:item.sha256},key=>api<ImageView>('/api/v1/merchant/products/'+product.productId+'/images',{method:'POST',body,key}))
  if(mine!==imageGeneration)return;if(result===undefined){item.state='unknown';imageNotice.value='上传结果尚未确认。请保留这些文件后重试；刷新后重新选择同一文件，可使用原请求编号恢复。';return}item.state='saved';await imageCommand.reset()
 }imageNotice.value='所选图片上传结果已确认。';await loadImages()
 }finally{uploadBusy.value=false}
}
/** 删除为同资源幂等操作，未知时可点击同一图片继续确认；从不通过列表缺失推断其他请求失败。 */
async function removeImage(image:ImageView){const product=imageProduct.value;if(!product)return;const mine=imageGeneration;const result=await imageCommand.run('remove:'+image.imageNo,{productId:product.productId,imageNo:image.imageNo},key=>api<string>('/api/v1/merchant/products/'+product.productId+'/images/'+image.imageNo,{method:'DELETE',key}));if(mine!==imageGeneration||result===undefined)return;await imageCommand.reset();if(mine===imageGeneration){imageNotice.value='图片已删除。';await loadImages()}}
watch(tab,()=>{notice.value='';if(tab.value==='ledger')void ledger.reload();if(tab.value==='conditions')void conditions.reload()})
watch(()=>session.user?.userId,()=>{close();products.clear();ledger.clear();conditions.clear();closeImages();keyword.value='';appliedKeyword.value='';conditionForm.value={skuId:'',fromCondition:'QUARANTINE',toCondition:'SALEABLE',quantity:'',reason:''};notice.value=''})
onMounted(()=>products.reload())
</script>
<template>
 <PageHeader title="商品与库存" description="维护商品版本和SKU价格，库存调整保留业务依据与流水。"><template #actions><ElButton v-if="can('MANAGE_PRODUCTS')" type="primary" @click="open('create')">新增商品</ElButton></template></PageHeader>
 <p v-if="notice" class="notice success-note" role="status">{{notice}}</p><Feedback :error="command.error.value"/>
 <section class="panel"><ElTabs v-model="tab"><ElTabPane label="商品目录" name="products"/><ElTabPane label="库存流水" name="ledger"/><ElTabPane label="不可售库存处置" name="conditions"/></ElTabs><div class="toolbar"><span class="muted">{{tab==='products'?'所属商家商品 · 含草稿与下架商品':'所属商家仓库 · warehouse_main'}}</span><div class="toolbar-controls"><form v-if="tab==='products'" class="product-search" @submit.prevent="searchProducts"><label class="sr-only" for="admin-product-keyword">搜索商品名称或描述</label><ElInput id="admin-product-keyword" v-model="keyword" maxlength="100" clearable placeholder="商品名称或描述"/><ElButton native-type="submit" :loading="products.loading.value">搜索商品</ElButton></form><ElButton v-if="tab==='ledger'&&can('MANAGE_INVENTORY')" type="primary" @click="open('inventory')">调整库存</ElButton><ElButton :loading="active.loading.value" @click="active.reload">刷新列表</ElButton></div></div>
 <Feedback :loading="active.loading.value" :error="active.error.value"/>
 <template v-if="!active.loading.value&&!active.error.value"><EmptyState v-if="!active.items.value.length" :title="tab==='products'?'当前页暂无商品':'当前页暂无库存流水'"/>
 <ElTable v-else-if="tab==='products'" :data="list" row-key="productId"><ElTableColumn type="expand"><template #default="{row:p}"><div class="sku-expansion"><p class="muted">{{p.description||'暂无商品描述'}}</p><div class="inline-actions product-tools"><ElButton v-if="can('MANAGE_PRODUCTS')" @click="open('addSku',p)">新增规格</ElButton><ElButton @click="openImages(p)">管理商品图片</ElButton></div><ElTable :data="p.skus"><ElTableColumn prop="skuCode" label="SKU编码" min-width="130"/><ElTableColumn prop="specification" label="规格" min-width="160"/><ElTableColumn label="单价" width="110"><template #default="{row:s}">{{money(s.priceCents)}}</template></ElTableColumn><ElTableColumn prop="availableQty" label="可售库存" width="100"/><ElTableColumn prop="reservedQty" label="预占库存" width="100"/><ElTableColumn label="状态" width="100"><template #default="{row:s}"><StatusBadge :status="s.status"/></template></ElTableColumn><ElTableColumn label="操作" min-width="210"><template #default="{row:s}"><ElButton v-if="can('MANAGE_PRODUCTS')" @click="open('sku',p,s)">编辑SKU</ElButton><ElButton v-if="can('MANAGE_INVENTORY')" @click="open('inventory',p,s)">调整库存</ElButton></template></ElTableColumn></ElTable></div></template></ElTableColumn><ElTableColumn prop="name" label="商品" min-width="200"/><ElTableColumn prop="productId" label="商品编号" min-width="130"/><ElTableColumn label="状态" width="130"><template #default="{row:p}"><StatusBadge :status="p.status"/></template></ElTableColumn><ElTableColumn prop="version" label="当前版本" width="100"/><ElTableColumn label="操作" width="130"><template #default="{row:p}"><ElButton v-if="can('MANAGE_PRODUCTS')" @click="open('product',p)">编辑商品</ElButton><span v-else class="muted">只读</span></template></ElTableColumn></ElTable>
 <ElTable v-else-if="tab==='ledger'" :data="ledger.items.value"><ElTableColumn prop="businessNo" label="业务单据" min-width="220"/><ElTableColumn prop="skuId" label="SKU编号" min-width="120"/><ElTableColumn prop="operationType" label="操作类型" min-width="140"/><ElTableColumn prop="availableDelta" label="可售变动" width="100"/><ElTableColumn prop="reservedDelta" label="预占变动" width="100"/><ElTableColumn prop="availableAfter" label="变动后可售" width="110"/><ElTableColumn prop="reservedAfter" label="变动后预占" width="110"/><ElTableColumn prop="createdAt" label="记账时间" min-width="200"/></ElTable>
 <template v-else><p class="notice">待检和残次不参与销售。报损保留不可变处置单据，不增加可售数量。</p><ElTable :data="conditions.items.value"><ElTableColumn prop="skuId" label="SKU"/><ElTableColumn label="状态"><template #default="{row:c}">{{conditionLabels[String(c.stockCondition)]??c.stockCondition}}</template></ElTableColumn><ElTableColumn prop="quantity" label="当前数量"/><ElTableColumn prop="version" label="版本"/></ElTable><ElForm v-if="can('MANAGE_INVENTORY')" label-position="top" @submit.prevent="changeCondition"><h3>受控实物处置</h3><ElFormItem label="SKU编号" required><ElInput v-model="conditionForm.skuId"/></ElFormItem><ElFormItem label="来源状态" required><ElSelect v-model="conditionForm.fromCondition"><ElOption label="待检隔离" value="QUARANTINE"/><ElOption label="残次保留" value="DAMAGED"/></ElSelect></ElFormItem><ElFormItem label="目标状态" required><ElSelect v-model="conditionForm.toCondition"><ElOption v-for="(label,value) in conditionLabels" :key="value" :label="label" :value="value"/></ElSelect></ElFormItem><ElFormItem label="处置数量" required><ElInput v-model="conditionForm.quantity" inputmode="numeric"/></ElFormItem><ElFormItem label="检验、维修或报损依据" required><ElInput v-model="conditionForm.reason" type="textarea" maxlength="500"/></ElFormItem><Feedback :error="localError||command.error.value"/><ElButton native-type="submit" type="primary" :loading="command.busy.value">确认处置</ElButton><ElButton :disabled="command.busy.value" @click="recoverCondition">查询原处置结果</ElButton></ElForm></template>
 </template><Pagination :page="active.page.value" :count="active.items.value.length" :total="active.total.value" :has-next="active.hasNext.value" :loading="active.loading.value" @change="active.change"/></section>
 <ElDialog :model-value="!!modal" :title="({create:'新增商品',product:'编辑商品',sku:'编辑SKU',addSku:'新增SKU',inventory:'库存调整'} as Record<string,string>)[modal]" width="620px" @close="close"><ElForm label-position="top" @submit.prevent="submit">
 <p v-if="selected&&(modal==='product'||modal==='sku')" class="notice">基于版本 {{sku?.version??selected.version}} 提交；发生版本冲突请关闭并刷新核对。</p>
 <template v-if="modal==='create'||modal==='product'"><ElFormItem label="商品名称" required><ElInput v-model="form.name" maxlength="200"/></ElFormItem><ElFormItem label="商品描述"><ElInput v-model="form.description" type="textarea" maxlength="2000" :rows="3"/></ElFormItem><ElFormItem label="商品状态" required><ElSelect v-model="form.status"><ElOption label="草稿" value="DRAFT"/><ElOption label="上架" value="ON_SALE"/><ElOption label="下架" value="OFF_SALE"/></ElSelect></ElFormItem></template>
 <template v-if="modal==='create'||modal==='addSku'"><div class="form-grid"><ElFormItem label="SKU编码" required><ElInput v-model="form.skuCode" maxlength="64"/></ElFormItem><ElFormItem label="规格"><ElInput v-model="form.specification" maxlength="500"/></ElFormItem></div><p class="field-hint">新增规格初始库存为零，编码仅支持字母、数字、下划线与短横线。</p></template>
 <ElFormItem v-if="modal==='create'||modal==='sku'||modal==='addSku'" label="销售单价（元）" required><ElInput v-model="form.price" inputmode="decimal" placeholder="例如 29.90"/></ElFormItem><ElFormItem v-if="modal==='sku'" label="SKU状态" required><ElSelect v-model="form.status"><ElOption label="启用" value="ACTIVE"/><ElOption label="停用" value="DISABLED"/></ElSelect></ElFormItem>
 <template v-if="modal==='inventory'"><p class="notice">仓库 warehouse_main。负数为扣减，系统会复核库存约束；受理后请查询流水。</p><ElFormItem label="SKU编号" required><ElInput v-model="form.skuId"/></ElFormItem><ElFormItem label="调整数量（整数）" required><ElInput v-model="form.quantity" inputmode="numeric" placeholder="例如 10 或 -2"/></ElFormItem><ElFormItem label="调整原因" required><ElInput v-model="form.reason" type="textarea" maxlength="500" :rows="3"/></ElFormItem></template>
 <Feedback :error="localError||command.error.value"/><div class="inline-actions"><ElButton type="primary" native-type="submit" :loading="command.busy.value">确认提交</ElButton><ElButton @click="close">关闭</ElButton></div></ElForm></ElDialog>
 <ElDialog :model-value="!!imageProduct" :title="(imageProduct?.name||'商品')+' · 图片'" width="min(760px, 94vw)" @close="closeImages">
  <p class="field-hint">最多十张PNG或JPEG图片，每张不超过5MiB。草稿图片仅当前店铺可预览，上架后公开展示。</p>
  <Feedback :loading="imageLoading" :error="imageError||imageCommand.error.value"/><p v-if="imageNotice" class="notice" role="status">{{imageNotice}}</p>
  <div class="image-gallery"><article v-for="image in imageRows" :key="image.imageNo" class="image-tile"><img v-if="image.preview&&!image.failed" :src="image.preview" :alt="imageProduct?.name+'商品图片'" width="220" height="160" @error="image.failed=true"/><p v-else class="muted">{{image.failed?'图片读取失败':'正在读取图片…'}}</p><span class="small muted">{{Math.ceil(image.sizeBytes/1024)}} KiB</span><ElButton v-if="can('MANAGE_PRODUCTS')" type="danger" plain :disabled="uploadBusy||imageCommand.busy.value" @click="removeImage(image)">删除图片</ElButton></article></div>
  <EmptyState v-if="!imageLoading&&!imageRows.length&&!imageError" title="尚未添加商品图片"/>
  <ElButton :disabled="uploadBusy" :loading="imageLoading" @click="loadImages">重新读取图片</ElButton>
  <div v-if="can('MANAGE_PRODUCTS')" class="upload-section"><label for="product-image-files">选择商品图片</label><input id="product-image-files" type="file" accept="image/png,image/jpeg" multiple :disabled="uploadBusy||imageCommand.busy.value" @change="selectFiles"/><ul v-if="uploadItems.length"><li v-for="item in uploadItems" :key="item.sha256">{{item.file.name}} · {{item.state==='saved'?'已确认':item.state==='unknown'?'待确认，可按原文件重试':'等待上传'}}</li></ul><ElButton type="primary" :loading="uploadBusy||imageCommand.busy.value" :disabled="!uploadItems.length||imageLoading" @click="uploadImages">上传或恢复所选图片</ElButton></div>
 </ElDialog>
</template>
<style scoped>.sku-expansion{padding:8px 24px 24px;background:#fafbfd}.product-search{display:flex;gap:8px;flex-wrap:wrap}.product-search .el-input{width:220px}.product-tools{margin-bottom:16px}.image-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin:16px 0}.image-tile{display:flex;flex-direction:column;gap:10px;align-items:start;border:1px solid #e5e7eb;padding:12px;border-radius:8px}.image-tile img{width:100%;height:160px;object-fit:contain;background:#f7f8fa}.image-tile>p{min-height:140px}.upload-section{display:flex;flex-direction:column;align-items:start;gap:12px;margin-top:24px}.upload-section input{max-width:100%}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:600px){.product-search{width:100%}.product-search .el-input{flex:1;width:auto}.image-gallery{grid-template-columns:1fr}}</style>
